input.command:
$base = "C:\Users\Administrator\.grok\sessions"
Get-ChildItem $base | Sort-Object LastWriteTime -Descending | ForEach-Object { "$($_.LastWriteTime) | $($_.Mode) | $($_.Name)" }
# Decode and list 海外仓 session
$hw = Get-ChildItem $base -Directory | Where-Object { $_.Name -like "*E%3A%5Cproject%5C%E6%B5%B7%E5%A4%96%E4%BB%93" -and $_.Name -notlike "*sellfox*" }
"--- HW path: $($hw.FullName) ---"
Get-ChildItem $hw.FullName -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 50 | ForEach-Object { "$($_.LastWriteTime) | $($_.Length) | $($_.FullName.Substring($hw.FullName.Length))" }
